select case when stores.sqft >= 16770 then 'high' when stores.sqft >= 5081 then 'mid' else 'low' end as sqft_bucket, max(store_sales.sale_date) as latest_sale_date, count(store_sales.revenue) as revenue_count from store_sales inner join stores on stores.id = store_sales.store_id left join products on store_sales.product_id = products.id group by case when stores.sqft >= 16770 then 'high' when stores.sqft >= 5081 then 'mid' else 'low' end order by revenue_count, sqft_bucket
